"""Explicit Runge-Kutta tableaus for the Lawson interaction-picture solver.

Sources: SciPy ``_ivp/rk.py`` and ``dop853_coefficients.py`` (BSD-3-Clause),
and OrdinaryDiffEq.jl ``verner_tableaus.jl`` generic constructors (MIT).
Original methods: Dormand & Prince (1980), Prince & Dormand (1981),
Hairer, Nørsett & Wanner (DOP853), and Verner (2010).
Rationals retain exact source values; radical expressions use high-precision decimals.
"""
from __future__ import annotations

from dataclasses import dataclass
from fractions import Fraction as Q


@dataclass(frozen=True)
class Tableau:
    name: str
    order: int
    embedded_order: int | None
    A: tuple[tuple[Q, ...], ...]
    b: tuple[Q, ...]
    c: tuple[Q, ...]
    b_hat: tuple[Q, ...] | None = None
    b_hat3: tuple[Q, ...] | None = None
    e5: tuple[Q, ...] | None = None
    e3: tuple[Q, ...] | None = None

    @property
    def stages(self) -> int:
        return len(self.b)


